const s=r=>{if(!r)return"Date non définie";try{const e=new Date(r);if(isNaN(e.getTime()))return"Date invalide";const t=["Dimanche","Lundi","Mardi","Mercredi","Jeudi","Vendredi","Samedi"],n=["Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre"],o=t[e.getDay()],a=e.getDate(),i=n[e.getMonth()],c=e.getFullYear();return`${o} ${a} ${i} ${c}`}catch(e){return console.error("Erreur formatage date:",e),"Date invalide"}};export{s as f};
